// Rotate news sources and implement 4-1-1 posting strategy
const sources = [
  {
    name: 'Google News - Injection Molding',
    url: 'https://news.google.com/rss/search?q=injection+molding+OR+mold+making+OR+plastic+injection+OR+tooling&hl=en-US&gl=US&ceid=US:en'
  },
  {
    name: 'Google News - Reshoring & Manufacturing',
    url: 'https://news.google.com/rss/search?q=manufacturing+reshoring+OR+reshoring+OR+nearshoring+manufacturing&hl=en-US&gl=US&ceid=US:en'
  },
  {
    name: 'Google News - China Manufacturing',
    url: 'https://news.google.com/rss/search?q=china+manufacturing+OR+china+supply+chain+OR+china+tooling&hl=en-US&gl=US&ceid=US:en'
  },
  {
    name: 'Google News - Sustainable Manufacturing',
    url: 'https://news.google.com/rss/search?q=sustainable+manufacturing+OR+sustainable+plastics+OR+recycled+plastics&hl=en-US&gl=US&ceid=US:en'
  },
  {
    name: 'Google News - Tariffs & Trade',
    url: 'https://news.google.com/rss/search?q=china+tariffs+manufacturing+OR+trade+war+manufacturing+OR+import+tariffs+plastics&hl=en-US&gl=US&ceid=US:en'
  },
  {
    name: 'Google News - Automation & Industry 4.0',
    url: 'https://news.google.com/rss/search?q=manufacturing+automation+OR+industry+4.0+OR+smart+manufacturing&hl=en-US&gl=US&ceid=US:en'
  }
];

const now = new Date();
const dayOfWeek = now.getDay();
const hour = now.getHours();

// Calculate post number (0-5 for 6 posts = 3 days of 2x daily)
const postNumber = (dayOfWeek * 2 + (hour > 12 ? 1 : 0)) % 6;

// 4-1-1 Strategy:
// Posts 0,1,2,3 = Value (share news with commentary)
// Post 4 = Authority (thought leadership, no link)
// Post 5 = Convert (soft CTA)
let postType = 'value';
if (postNumber === 4) {
  postType = 'authority';
} else if (postNumber === 5) {
  postType = 'convert';
}

const sourceIndex = postNumber % sources.length;
const selectedSource = sources[sourceIndex];

return [{
  json: {
    sourceName: selectedSource.name,
    sourceUrl: selectedSource.url,
    postType: postType,
    postNumber: postNumber
  }
}];

// Extract news items and pick a random one
const data = $input.first().json;
const sourceData = $('Select Daily Source').first().json;
let items = [];

if (data.rss && data.rss.channel && data.rss.channel.item) {
  items = Array.isArray(data.rss.channel.item) ? data.rss.channel.item : [data.rss.channel.item];
} else if (data.feed && data.feed.entry) {
  items = Array.isArray(data.feed.entry) ? data.feed.entry : [data.feed.entry];
}

if (items.length === 0) {
  return [{ json: { 
    error: 'No articles found', 
    title: 'Industry insights from the field', 
    source: 'Industry Experience', 
    link: '',
    postType: sourceData.postType,
    postNumber: sourceData.postNumber
  }}];
}

const randomIndex = Math.floor(Math.random() * Math.min(items.length, 10));
const article = items[randomIndex];

const title = article.title && typeof article.title === 'object' ? article.title['#text'] || article.title._ || String(article.title) : article.title || 'Industry Update';
const source = article.source ? (article.source['#text'] || article.source._ || String(article.source)) : 'Industry News';

// Get the link - for Google News this is the redirect URL which will still show preview
let link = '';
if (article.link && typeof article.link === 'object') {
  link = article.link.href || article.link['#text'] || String(article.link);
} else {
  link = article.link || '';
}

return [{
  json: {
    title: title,
    link: link,
    source: source,
    postType: sourceData.postType,
    postNumber: sourceData.postNumber
  }
}];

// Build the appropriate prompt based on post type
const data = $input.first().json;
const postType = data.postType;

let prompt = '';

if (postType === 'value') {
  prompt = `You are Brandon, Technical Sales Support Manager of the Americas for TK Mold and owner of MoldMinds - the offshore tooling partner for customers across the globe. You're THE China mold source for global manufacturers.

Write an X post sharing this industry news with your expert commentary:
Title: ${data.title}
Source: ${data.source}

Rules:
- Keep under 240 characters (leave room for article link)
- Lead with YOUR expert take or insight, not a summary of the article
- Sound like an industry insider sharing news with peers
- End with an engagement hook (question, bold take, or insight that invites discussion)
- No hashtags unless highly relevant
- DO NOT include any URL - the link will be added separately
- Output ONLY the post text, nothing else`;

} else if (postType === 'authority') {
  prompt = `You are Brandon, Technical Sales Support Manager of the Americas for TK Mold and owner of MoldMinds - the offshore tooling partner for customers across the globe. You're THE China mold source for global manufacturers with years of experience navigating complex sourcing relationships.

Write an original thought leadership X post about a challenge, insight, or trend in injection molding and mold sourcing. Draw from experience with:
- Building and maintaining China manufacturing relationships
- Navigating tariff impacts and supply chain shifts
- Quality vs cost tradeoffs that most buyers get wrong
- What separates great tooling partners from the rest
- Lessons learned from sourcing 100s of tools across Asia
- The reality of offshore tooling that nobody talks about

This news might inspire your thinking: ${data.title}

Rules:
- Keep under 280 characters
- Share a hard-won insight, contrarian take, or truth bomb
- Make readers think "damn, I never thought of it that way"
- Be direct and confident - you've earned these opinions
- NO selling, NO CTA - just pure value and expertise
- No hashtags
- Output ONLY the post text, nothing else`;

} else if (postType === 'convert') {
  prompt = `You are Brandon, Technical Sales Support Manager of the Americas for TK Mold and owner of MoldMinds - the offshore tooling partner for customers across the globe. You're THE China mold source for global manufacturers.

You're also a skilled consultative salesperson who knows that the best sales don't feel like sales. You solve problems. You're the guy people call when they need straight talk about sourcing molds from Asia.

Write an X post about this industry news with a natural, soft call-to-action:
Title: ${data.title}
Source: ${data.source}

Rules:
- Keep under 200 characters (leave room for link + CTA)
- Start with brief, insightful commentary on the news
- End with a helpful, peer-to-peer CTA that feels natural
- Good CTA examples:
  - "Navigating these changes? Happy to share what we're seeing on the ground - brandon@tkmold.com"
  - "If you're rethinking your tooling strategy, let's talk - brandon@tkmold.com"
  - "Dealing with this right now? I've got some thoughts - brandon@tkmold.com"
- The CTA should feel like a friend offering help, NOT a sales pitch
- No hashtags
- DO NOT include the article URL - it will be added separately
- Output ONLY the post text, nothing else`;
}

return [{
  json: {
    title: data.title,
    link: data.link,
    source: data.source,
    postType: postType,
    prompt: prompt
  }
}];

// Combine Claude output with article link based on post type
const claudeOutput = $input.first().json;
const promptData = $('Build Prompt by Type').first().json;

let postText = claudeOutput.content[0].text;
const postType = promptData.postType;
const articleLink = promptData.link;

// Add article link for value and convert posts (not authority)
if (postType !== 'authority' && articleLink) {
  postText = postText + '\n\n' + articleLink;
}

return [{
  json: {
    finalPost: postText,
    postType: postType
  }
}];
